    states<S extends string>(states: readonly State<S>[], initial: NoInfer<S>): KindDescriptor<T, S>;
  }
  export interface KindDescriptor<T, S extends string> extends Kind<T, S> {
    failsTo(state: S): KindDescriptor<T, S>;
  }

